/**
 * Synchronous datasheet extraction via Anthropic Messages API.
 * Supports both Haiku (default) and Sonnet (fallback for large PDFs).
 */

import { DATASHEET_EXTRACTION_PROMPT } from './prompt.ts';
import { normalizeAndParseExtraction } from './result-parser.ts';
import type { ExtractionResult } from './result-parser.ts';

export const HAIKU_MODEL = 'claude-haiku-4-5-20251001';
export const SONNET_MODEL = 'claude-sonnet-4-6';

const ANTHROPIC_API_URL = 'https://api.anthropic.com/v1/messages';
const ANTHROPIC_VERSION = '2023-06-01';

/** Whether a model supports assistant message prefill. */
function supportsAssistantPrefill(model: string): boolean {
  // Sonnet 4.6+ / Opus 4.6+ do not support assistant prefill
  return !model.startsWith('claude-sonnet-4-6')
      && !model.startsWith('claude-opus-4-6')
      && !model.startsWith('claude-opus-4-7');
}

export interface SyncExtractionResult {
  success: boolean;

