  'claude-opus-4-7': { input: 500, output: 2500, cacheWrite: 625, cacheRead: 50 },           // $5/$25/$6.25/$0.50 per 1M
  'claude-opus-4-6': { input: 500, output: 2500, cacheWrite: 625, cacheRead: 50 },           // $5/$25/$6.25/$0.50 per 1M
  'claude-sonnet-4-6': { input: 300, output: 1500, cacheWrite: 375, cacheRead: 30 },         // $3/$15/$3.75/$0.30 per 1M
  'claude-haiku-4-5-20251001': { input: 100, output: 500, cacheWrite: 125, cacheRead: 10 },  // $1/$5/$1.25/$0.10 per 1M
  'claude-3-haiku-20240307': { input: 25, output: 125, cacheWrite: 0, cacheRead: 0 },        // $0.25/$1.25 per 1M (retired; kept for historical rows)
  'gemini-3.1-pro-preview': { input: 200, output: 1200, cacheWrite: 200, cacheRead: 20 },       // $2/$12 per 1M, cache read $0.20/1M (implicit caching, no separate write cost)
  'gemini-3.1-pro-preview-customtools': { input: 200, output: 1200, cacheWrite: 200, cacheRead: 20 },
}

// Compute cost in cents from token counts and model pricing.
// Applies COST_MARKUP_MULTIPLIER to provider costs.
export function computeCostFromTokens(
  model: string,
  inputTokens: number,
  outputTokens: number,
  cacheCreationTokens: number = 0,
  cacheReadTokens: number = 0,
): number {
  const costs = MODEL_COSTS[model]
  if (!costs) return 0

  return Math.round(
    (inputTokens * costs.input +
      outputTokens * costs.output +
      cacheCreationTokens * costs.cacheWrite +
      cacheReadTokens * costs.cacheRead) * COST_MARKUP_MULTIPLIER /
      1_000_000
  )
}

// Web search pricing: $10 per 1,000 searches = $0.01 per search = 1 cent
export const WEB_SEARCH_COST_CENTS = 1

// Web fetch content limit — cap fetched content to control token costs (~500KB PDF)
export const WEB_FETCH_MAX_CONTENT_TOKENS = 125_000

// Markup applied to provider costs — matches Stripe Token Billing pricing plan
export const COST_MARKUP_MULTIPLIER = 1.10  // 10%

// --- Anthropic API retry ---

/**
 * Fetch with retry for non-streaming Anthropic API calls.
 * Retries on 429 (rate limit), 529 (overloaded), and network errors.
 * Max 3 retries with exponential backoff (1s, 2s, 4s).
 */
export async function fetchWithRetry(
  url: string,
  init: RequestInit,
  maxRetries: number = 3,
): Promise<Response> {
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      const response = await fetch(url, init)

      if (response.ok || attempt === maxRetries) return response

      // Retry on rate limit or overloaded
      const status = response.status
      if (status === 429 || status === 529 || status >= 500) {
        const delay = Math.pow(2, attempt) * 1000 // 1s, 2s, 4s
        console.warn(`Anthropic API ${status}, retrying in ${delay}ms (attempt ${attempt + 1}/${maxRetries})`)
        await new Promise(r => setTimeout(r, delay))
        continue
      }

      // Non-retryable error (400, 401, etc.)
      return response
    } catch (err) {
      if (attempt === maxRetries) throw err
      const delay = Math.pow(2, attempt) * 1000
      console.warn(`Anthropic API network error, retrying in ${delay}ms (attempt ${attempt + 1}/${maxRetries}):`, err)
      await new Promise(r => setTimeout(r, delay))
    }
  }

  // Should never reach here, but TypeScript needs it
  throw new Error('fetchWithRetry: exhausted retries')
}

// --- Billing configuration ---

// Spending limit for free-tier users (no free credits — hard cap)
export const FREE_SPENDING_LIMIT_CENTS = 0  // $0.00 — free tier has no credits

// Credit grant for dev-plan users (metered in Stripe but covered by credits)
export const DEV_CREDITS_CENTS = 500_000  // $5,000.00

// Default spending limit for paid users (with payment method)
export const DEFAULT_SPENDING_LIMIT_CENTS = 5_000  // $50.00

// Free starter credits for new users (granted once on first sign-up, lifetime budget)
export const STARTER_CREDITS_CENTS = parseInt(process.env.STARTER_CREDITS_CENTS || '1500', 10)  // $15.00
export const EDU_STARTER_CREDITS_CENTS = parseInt(process.env.EDU_STARTER_CREDITS_CENTS || '5000', 10)  // $50.00

/** Returns the appropriate starter credit amount based on the user's email. */
export function getStarterCredits(email: string): number {
  if (email && email.toLowerCase().endsWith('.edu')) return EDU_STARTER_CREDITS_CENTS
  return STARTER_CREDITS_CENTS
}

import { getStripe } from './stripe'

const TOKEN_METER_EVENT_NAME = process.env.STRIPE_TOKEN_METER_EVENT_NAME

// Map internal model IDs to Stripe rate card model names
const MODEL_TO_RATE_CARD: Record<string, string> = {
  'claude-opus-4-7': 'anthropic/claude-opus-4.5',
  'claude-opus-4-6': 'anthropic/claude-opus-4.5',
  'claude-sonnet-4-6': 'anthropic/claude-sonnet-4.5',
  'claude-3-haiku-20240307': 'anthropic/claude-haiku-4.5',
  'gemini-3.1-pro-preview': 'google/gemini-3.1-pro-preview',
  'gemini-3.1-pro-preview-customtools': 'google/gemini-3.1-pro-preview',
}

interface TokenUsageReport {
  stripeCustomerId: string
  model: string
  inputTokens: number
  outputTokens: number
  cacheCreationTokens: number
  cacheReadTokens: number
}

/**
 * Report raw token usage to Stripe Token Billing.
 * Model names and token types must match the pricing plan rate card.
 */
export async function reportTokenUsageToStripe(usage: TokenUsageReport): Promise<void> {
  if (!TOKEN_METER_EVENT_NAME || !usage.stripeCustomerId) return

  const rateCardModel = MODEL_TO_RATE_CARD[usage.model] || usage.model
  const stripe = getStripe()

  const events: Array<{ tokenType: string; value: number }> = [
    { tokenType: 'input', value: usage.inputTokens },
    { tokenType: 'output', value: usage.outputTokens },
    { tokenType: 'cached_input', value: usage.cacheReadTokens },
    { tokenType: 'cached_output', value: usage.cacheCreationTokens },
  ]

  for (const event of events) {
    if (event.value <= 0) continue
    try {
      await stripe.billing.meterEvents.create({
        event_name: TOKEN_METER_EVENT_NAME,
        payload: {
          stripe_customer_id: usage.stripeCustomerId,
          value: String(event.value),
          model: rateCardModel,
          token_type: event.tokenType,
        },
      })
    } catch (err) {
      console.error(`Failed to report ${event.tokenType} tokens to Stripe:`, err)
    }
  }
}

