/**
 * Synchronous datasheet extraction via Anthropic Messages API.
 * Supports both Haiku (default) and Sonnet (fallback for large PDFs).
 */

import { DATASHEET_EXTRACTION_PROMPT } from './prompt.ts';
import { normalizeAndParseExtraction } from './result-parser.ts';
import type { ExtractionResult } from './result-parser.ts';

export const HAIKU_MODEL = 'claude-haiku-4-5-20251001';
export const SONNET_MODEL = 'claude-sonnet-4-6';

const ANTHROPIC_API_URL = 'https://api.anthropic.com/v1/messages';
const ANTHROPIC_VERSION = '2023-06-01';

/** Whether a model supports assistant message prefill. */
function supportsAssistantPrefill(model: string): boolean {
  // Sonnet 4.6+ / Opus 4.6+ do not support assistant prefill
  return !model.startsWith('claude-sonnet-4-6')
      && !model.startsWith('claude-opus-4-6')
      && !model.startsWith('claude-opus-4-7');
}

export interface SyncExtractionResult {
  success: boolean;
  data?: ExtractionResult;
  error?: string;
  inputTokens: number;
  outputTokens: number;
  model: string;
  /** True if the failure was due to PDF size/page limits (eligible for Sonnet retry). */
  isSizeError?: boolean;
}

/**
 * Extract datasheet data synchronously via the Messages API.
 * Blocks until the extraction is complete (typically 30-60s for a PDF).
 */
export async function extractDatasheetSync(
  pdfBase64: string,
  partNumber?: string,
  manufacturer?: string,
  model: string = HAIKU_MODEL,
): Promise<SyncExtractionResult> {
  const apiKey = Deno.env.get('ANTHROPIC_API_KEY');
  if (!apiKey) {
    throw new Error('ANTHROPIC_API_KEY not configured');
  }

  const userPrompt = partNumber
    ? `Extract all component data from this datasheet for: ${partNumber}${manufacturer ? ` by ${manufacturer}` : ''}`
    : 'Extract all component data from this datasheet. Identify the part number and manufacturer from the document.';

  const usePrefill = supportsAssistantPrefill(model);

  const messages: Array<Record<string, unknown>> = [
    {
      role: 'user',
      content: [
        {
          type: 'document',
          source: {
            type: 'base64',
            media_type: 'application/pdf',
            data: pdfBase64,
          },
        },
        {
          type: 'text',
          text: usePrefill
            ? userPrompt
            : userPrompt + ' Return only the raw JSON object with no markdown formatting or code fences.',
        },
      ],
    },
  ];

  if (usePrefill) {
    messages.push({ role: 'assistant', content: '{' });
  }

  const requestBody = {
    model,
    max_tokens: 64000,
    system: DATASHEET_EXTRACTION_PROMPT,
    messages,
  };

  // 400s timeout — matches Supabase edge function wall clock limit (Pro plan)
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 400_000);

  let response: Response;
  try {
    response = await fetch(ANTHROPIC_API_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': apiKey,
        'anthropic-version': ANTHROPIC_VERSION,
      },
      body: JSON.stringify(requestBody),
      signal: controller.signal,
    });
    clearTimeout(timeoutId);
  } catch (err) {
    clearTimeout(timeoutId);
    const message = err instanceof Error ? err.message : String(err);
    return {
      success: false,
      error: `Extraction request failed: ${message}`,
      inputTokens: 0,
      outputTokens: 0,
      model,
    };
  }

  if (!response.ok) {
    const errorText = await response.text();

    // Detect specific API limits — these are eligible for Sonnet retry
    if (errorText.includes('maximum of 100 PDF pages') || errorText.includes('maximum of 600 PDF pages')) {
      return {
        success: false,
        error: 'Datasheet is too large — exceeds the PDF page limit.',
        inputTokens: 0,
        outputTokens: 0,
        model,
        isSizeError: true,
      };
    }
    if (errorText.includes('prompt is too long') || errorText.includes('too many tokens')) {
      return {
        success: false,
        error: 'Datasheet is too large — exceeds the model\'s input token limit.',
        inputTokens: 0,
        outputTokens: 0,
        model,
        isSizeError: true,
      };
    }

    return {
      success: false,
      error: `Messages API failed: HTTP ${response.status} — ${errorText}`,
      inputTokens: 0,
      outputTokens: 0,
      model,
    };
  }

  const result = await response.json();

  const inputTokens = result.usage?.input_tokens ?? 0;
  const outputTokens = result.usage?.output_tokens ?? 0;

  // Extract JSON from the response content
  const textBlock = result.content?.find((b: { type: string }) => b.type === 'text');
  if (!textBlock?.text) {
    return {
      success: false,
      error: 'No text content in response',
      inputTokens,
      outputTokens,
      model,
    };
  }

  try {
    // If we used assistant prefill, prepend the '{' we started with
    let rawJson = textBlock.text;
    if (usePrefill) {
      rawJson = '{' + rawJson;
    } else {
      // Strip markdown fences if present (Sonnet may wrap in ```)
      rawJson = rawJson.trim();
      if (rawJson.startsWith('```')) {
        rawJson = rawJson.replace(/^```\w*\n?/, '').replace(/\n?```$/, '');
      }
    }

    const data = normalizeAndParseExtraction(rawJson);

    return {
      success: true,
      data,
      inputTokens,
      outputTokens,
      model,
    };
  } catch (parseError) {
    // Detect truncated output — model hit context window or output limit
    const stopReason = result.stop_reason;
    const totalTokens = inputTokens + outputTokens;
    const likelyTruncated = stopReason === 'max_tokens'
      || stopReason === 'end_turn_max_tokens'
      || totalTokens > 180_000;

    if (likelyTruncated) {
      return {
        success: false,
        error: `Datasheet is too complex — extraction output was truncated (${inputTokens} input + ${outputTokens} output tokens).`,
        inputTokens,
        outputTokens,
        model,
        isSizeError: true,
      };
    }

    return {
      success: false,
      error: `Failed to parse extraction JSON: ${parseError instanceof Error ? parseError.message : String(parseError)}`,
      inputTokens,
      outputTokens,
      model,
    };
  }
}
